package ru.evolenta.pgs.worker;
import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.*;import static ru.evolenta.pgs.worker.Util.*;
/** Run with assertions enabled. No platform, database, network or real credentials. */
public final class SelfTest {
    private static int passed=0;
    private static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);passed++;}
    private static void rejects(Throwing task,String name)throws Exception{try{task.run();}catch(Exception expected){passed++;return;}throw new AssertionError("Expected rejection: "+name);}
    private interface Throwing{void run()throws Exception;}
    public static void main(String[] args)throws Exception{
        check(map(Json.parse("\uFEFF{\"x\":true}")).get("x").equals(true),"BOM JSON");
        check(Json.write(Json.parse("{\"текст\":\"a\\n\\t\\u0000\\\\\"}")).contains("\\u0000"),"JSON escaping");
        rejects(()->Json.parse("{\"x\":1,\"x\":2}"),"Duplicate JSON key");rejects(()->Json.parse("{} garbage"),"JSON trailing data");rejects(()->Json.parse("[01]"),"JSON number grammar");
        check(hash(obj("b",2,"a",1)).equals(hash(obj("a",1,"b",2))),"Canonical operation hash");
        Map<String,Object> task=task("ADVERTISING","PARSE_VALIDATE");Command command=new Command(task);check(command.domain==Command.Domain.ADVERTISING,"Advertising accepted");
        check(new Command(task("TRADE","PARSE_VALIDATE")).domain==Command.Domain.TRADE,"Trade accepted");check(new Command(task("PET","PARSE_VALIDATE")).domain==Command.Domain.PET,"Pet accepted");
        rejects(()->new Command(task("ADVERTISING","EXECUTE_ARBITRARY_CODE")),"Unknown operation");
        FakeApi api=new FakeApi();Context context=new Context(command,api);check("sub-current".equals(context.sub.get("guid")),"Exact subservice selected despite another ACTIVE subservice");
        api.appeal.put("subservices",Arrays.asList(api.sub("sub-other","other-process","other-info")));rejects(()->new Context(command,api),"Never fallback to first ACTIVE");
        check(XlsxReader.businessValue("45292","Дата начала").equals("01.01.2024"),"Excel serial date");check(XlsxReader.businessValue("0.5","Время начала").equals("12:00"),"Excel serial time");check(XlsxReader.businessValue("001234","ИНН").equals("001234"),"Leading zeros");check(XlsxReader.businessValue("a\nb","Название").contains("\n"),"Keep raw values for validation");
        Map<String,Object>selected=obj("region","Ростовская область","municipality","Тестовое МО","organization",obj("_id","org","inn","7706281123","ogrn","1027706014874"));
        Map<String,Object>draft=new XlsxReader().parse(workbook(false),obj("_id","file","originalName","test.xlsx"),selected);
        check(integer(draft.get("totalRows"))==1,"StAX business row");Map<String,Object>row=maps(maps(draft.get("sheets")).get(0).get("rows")).get(0);check(clean(AdvertisingValidator.cell(row,obj("column","D")).get("value")).equals("001234"),"Read shared/inline values without numeric coercion");
        rejects(()->new XlsxReader().parse(workbook(true),obj("_id","file"),selected),"DTD disabled");rejects(()->new XlsxReader().parse(new byte[0],obj(),selected),"Empty file");
        Map<String,Object>result=new AdvertisingValidator().validate(draft,obj(),selected,null);check(integer(result.get("totalErrors"))==1&&clean(map(list(result.get("errors")).get(0)).get("errorCode")).equals("STRUCTURE_FILE_CHANGED"),"Changed template gives one structure error");
        Map<String,Object>schema;try(InputStream in=SelfTest.class.getResourceAsStream("/advertising-validation.json")){schema=map(at(Json.read(in),"profiles.Реклама"));}
        Map<String,Object>schemaDraft=schemaDraft(schema);result=new AdvertisingValidator().validate(schemaDraft,obj(),selected,null);Set<String>codes=new HashSet<String>();for(Object o:list(result.get("errors")))codes.add(clean(map(o).get("errorCode")));check(codes.contains("REQUIRED"),"Required fields validated");check(codes.contains("IS_VALID_INN_OGRN"),"INN format validated");check(codes.contains("DOUBLE_SPACES"),"Raw spaces validated");check(codes.contains("PHOTO_FORMAT")&&codes.contains("PHOTO_MAIN_REQUIRED"),"Photo rules validated");check(bool(result.get("validationBlocked")),"Errors block import");check(!codes.contains("STRUCTURE_FILE_CHANGED"),"All 390 headers recognized");
        Path tmp=Files.createTempDirectory("pgs-journal-test-");try(Journal j=new Journal(tmp)){String k=hash("test");j.save(k,obj("status","COMPLETED","variables",obj("rbuCanApply",true)));check(clean(j.read(k).get("status")).equals("COMPLETED"),"Atomic checkpoint round trip");rejects(()->j.read("../escape"),"Journal path protection");FakeApi fake=new FakeApi();Context c=new Context(new Command(task("ADVERTISING","IMPORT_APPLY")),fake);Operations ops=new Operations(j,()->{});rejects(()->ops.execute(c),"Registry writes disabled by default");check(fake.writes==0,"No registry writes when disabled");}
        // Only this newly created test directory is removed, never a computed user path.
        try(java.util.stream.Stream<Path> entries=Files.list(tmp)){for(Path f:(Iterable<Path>)entries::iterator)Files.delete(f);}Files.delete(tmp);
        Path integration=Files.createTempDirectory("pgs-validation-flow-");try(Journal j=new Journal(integration)){
            IntegrationApi platform=new IntegrationApi();Command cmd=new Command(task("ADVERTISING","PARSE_VALIDATE"));Operations ops=new Operations(j,()->{});
            Map<String,Object>vars=ops.execute(new Context(cmd,platform));check(!bool(vars.get("rbuCanApply")),"Changed XLSX does not allow import");check(platform.writes==2,"Validation saves root and correct subservice");check(at(platform.appeal,"subservices.1.xsdData.rbuImportResult") instanceof Map,"Existing form receives result");check(at(platform.appeal,"subservices.0.xsdData.rbuImportResult")==null,"Other subservice untouched");
            ops.execute(new Context(cmd,platform));check(platform.writes==2,"Redelivery reuses durable result without repeating writes");
            IntegrationApi changed=new IntegrationApi();changed.changeFile=true;rejects(()->ops.execute(new Context(cmd,changed)),"Changed input during validation");check(changed.writes==0,"Never publish stale result");
            IntegrationApi lost=new IntegrationApi();rejects(()->new Operations(j,()->{throw new IllegalStateException("Lock lost");}).execute(new Context(cmd,lost)),"Lost external task lock");check(lost.writes==0,"No save after lost lock");
            check(list(at(platform.appeal,"importDraft.sheets.0.rows")).isEmpty(),"Raw rows are absent from the PGS case");
            Map<String,Object>privateSnapshot=j.read(clean(at(platform.appeal,"importDraft.workerValidationKey")));check(!list(at(privateSnapshot,"draft.sheets.0.rows")).isEmpty(),"Raw rows remain on worker durable volume");
            IntegrationApi half=new IntegrationApi();half.failSubOnce=true;Map<String,Object>publishTask=task("ADVERTISING","PARSE_VALIDATE");publishTask.put("id","publish-task");Command publishCommand=new Command(publishTask);rejects(()->ops.execute(new Context(publishCommand,half)),"Publication interrupted between root and subservice");check(half.writes==1,"Only root saved before simulated outage");ops.execute(new Context(publishCommand,half));check(half.writes==3&&at(half.appeal,"subservices.1.xsdData.rbuImportResult") instanceof Map,"Retry republishes durable result to the same subservice");
            IntegrationApi omsu=new IntegrationApi();omsu.appeal.put("unit",obj("id","org"));Map<String,Object>omsuTask=task("ADVERTISING","PARSE_VALIDATE");map(map(omsuTask.get("variables")).get("rbuProfile")).put("value","OMSU");Context omsuContext=new Context(new Command(omsuTask),omsu);check(!new AdvertisingGuard(omsuContext,false).organization.isEmpty(),"OMSU can validate its own organization");rejects(()->new AdvertisingGuard(omsuContext,true),"OMSU import requires isMigration");omsu.allowMigration=true;check(!new AdvertisingGuard(omsuContext,true).organization.isEmpty(),"OMSU import with granted permission");omsu.appeal.put("unit",obj("id","foreign"));rejects(()->new AdvertisingGuard(new Context(new Command(omsuTask),omsu),false),"OMSU cannot use another organization");IntegrationApi broken=new IntegrationApi();broken.brokenTerritory=true;rejects(()->new AdvertisingGuard(new Context(cmd,broken),false),"Missing municipality link blocks operation");

        }
        try(java.util.stream.Stream<Path> entries=Files.list(integration)){for(Path f:(Iterable<Path>)entries::iterator)Files.delete(f);}Files.delete(integration);
        System.out.println("PASS "+passed+" assertions");
    }
    private static Map<String,Object>task(String domain,String operation){Map<String,Object>v=obj();for(Map.Entry<String,Object>e:obj("mainId","appeal","collectionName","rbuModulesAppeals.subservices","camundaBusinessInfoId","info-current","rbuDomain",domain,"rbuProfile","ROIV","rbuOperation",operation,"rbuContractVersion","1").entrySet())v.put(e.getKey(),obj("type","String","value",e.getValue()));return obj("id","task","processInstanceId","process-current","activityId","Activity_02hj076","variables",v);}
    private static Map<String,Object>schemaDraft(Map<String,Object>schema){List<Object>sheets=new ArrayList<Object>();for(int n=2;n<=6;n++){List<Object>cols=new ArrayList<Object>();int index=1;for(Map<String,Object>f:maps(schema.get("fields")))if(clean(f.get("sheet")).equals("sheet"+n)){cols.add(obj("column",columnName(index++),"attribute",f.get("attribute"),"fieldName",f.get("name"),"block",f.get("block"),"subBlock",f.get("block"),"requiredMarker",bool(f.get("required"))?"Да":"Нет"));}List<Object>rows=new ArrayList<Object>();if(n==2){List<Object>cells=new ArrayList<Object>();for(Object o:cols){Map<String,Object>c=map(o);String v="";if(clean(c.get("fieldName")).equals("ОГРН")&&clean(c.get("column")).equals("D"))v="abc";if(clean(c.get("fieldName")).equals("Номер рекламной конструкции в схеме"))v="  двойной  пробел ";if(clean(c.get("column")).equals("GC"))v="photo.png";if(!v.isEmpty()){Map<String,Object>cell=copy(c);cell.put("value",v);cells.add(cell);}}rows.add(obj("rowNumber",6,"cells",cells));}sheets.add(obj("code","sheet"+n,"sheetName",XlsxReader.NAMES.get(n-1),"columns",cols,"rows",rows));}return obj("availableSheets",XlsxReader.NAMES,"sheets",sheets,"file",obj("sha256","hash","originalName","test.xlsx"),"referenceLists",obj("entries",Collections.emptyList()));}
    private static byte[]workbook(boolean dtd)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(out)){StringBuilder book=new StringBuilder("<workbook xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets>"),rels=new StringBuilder("<Relationships>");for(int i=1;i<=7;i++){book.append("<sheet name=\"").append(XlsxReader.NAMES.get(i-1)).append("\" r:id=\"r").append(i).append("\"/>");rels.append("<Relationship Id=\"r").append(i).append("\" Target=\"worksheets/sheet").append(i).append(".xml\"/>");String sheet="<worksheet><sheetData>"+(i==2?"<row r=\"4\"><c r=\"D4\" t=\"inlineStr\"><is><t>ИНН</t></is></c></row><row r=\"6\"><c r=\"D6\" t=\"inlineStr\"><is><t>001234</t></is></c></row>":"")+"</sheetData></worksheet>";if(dtd&&i==2)sheet="<!DOCTYPE worksheet [<!ENTITY x SYSTEM 'file:///DO_NOT_READ'>]>"+sheet;entry(z,"xl/worksheets/sheet"+i+".xml",sheet);}book.append("</sheets></workbook>");rels.append("</Relationships>");entry(z,"xl/workbook.xml",book.toString());entry(z,"xl/_rels/workbook.xml.rels",rels.toString());}return out.toByteArray();}
    private static void entry(ZipOutputStream z,String name,String xml)throws Exception{ZipEntry entry=new ZipEntry(name);entry.setTime(0);z.putNextEntry(entry);z.write(xml.getBytes(StandardCharsets.UTF_8));z.closeEntry();}
    private static final class FakeApi implements PgsApi{
        Map<String,Object>appeal;int writes;FakeApi(){appeal=obj("_id","appeal","guid","appeal-guid","subservices",Arrays.asList(sub("sub-other","other-process","other-info"),sub("sub-current","process-current","info-current")));}
        Map<String,Object>sub(String guid,String process,String info){return obj("guid",guid,"parentEntries","rbuModulesAppeals.subservices","camundaProcessInfo",obj("id",process,"camundaBusinessInfoId",info,"status","ACTIVE"),"xsdData",obj());}
        public Map<String,Object>find(String c,String id){return c.equals("rbuModulesAppeals")?copy(appeal):obj();}public List<Map<String,Object>>search(String c,List<Object>f,int p,int size){return Collections.emptyList();}public void update(String c,String id,String g,Map<String,Object>p){writes++;}public void updateSub(String c,String id,String g,String parent,Map<String,Object>p){writes++;}public Map<String,Object>create(String c,Map<String,Object>p){writes++;return obj();}public void delete(String c,String id,String g){writes++;}public byte[]download(String id,long max){return new byte[0];}
    }
    private static final class IntegrationApi implements PgsApi{
        Map<String,Object>appeal;int writes;boolean changeFile,failSubOnce,brokenTerritory,allowMigration;
        IntegrationApi(){FakeApi f=new FakeApi();appeal=f.appeal;appeal.putAll(obj("unit",obj("id","org"),"organization",obj("_id","org","guid","org-guid"),"region",obj("_id","region"),"municipality",obj("_id","municipality"),"importFile",obj("_id","file","size",100,"originalName","test.xlsx")));}
        public Map<String,Object>find(String c,String id){if(c.equals("rbuModulesAppeals"))return copy(appeal);if(c.equals("rbuRegionMunicipalAdvert"))return obj("_id","card","organizationGuid","org-guid","passport",obj("_id","region"),"municipality",brokenTerritory?obj():obj("_id","municipality"),"isMigration",allowMigration);if(c.equals("rbuRegionPassportsMarketing"))return obj("_id","region","regionCode","61","regionName","Ростовская область");if(c.equals("rbuRegionMunicipalitiesMarketing"))return obj("_id","municipality","municipalityName","Тестовое МО","passportId","region");if(c.equals("organizations"))return id.equals("foreign")?obj("_id","foreign","guid","foreign-guid"):organization();return obj();}
        private Map<String,Object>organization(){return obj("_id","org","guid","org-guid","name","Тестовая организация","regions",obj("code","61"),"inn","7706281123","ogrn","1027706014874");}
        public List<Map<String,Object>>search(String c,List<Object>f,int p,int size){return c.equals("organizations")?Arrays.asList(organization()):Collections.emptyList();}
        public void update(String c,String id,String guid,Map<String,Object>patch){writes++;appeal.putAll(patch);}
        public void updateSub(String c,String id,String guid,String parent,Map<String,Object>patch){if(failSubOnce){failSubOnce=false;throw new IllegalStateException("Simulated updateSub unavailable");}writes++;for(Map<String,Object>s:maps(appeal.get("subservices")))if(guid.equals(s.get("guid")))s.putAll(patch);}
        public Map<String,Object>create(String c,Map<String,Object>p){throw new AssertionError("Unexpected registry create");}public void delete(String c,String id,String g){throw new AssertionError("Unexpected registry delete");}
        public byte[]download(String id,long max)throws Exception{if(changeFile)appeal.put("importFile",obj("_id","new-file","originalName","new.xlsx"));return workbook(false);}
    }
}
